  'Saat switch ini hidup, Zephyr jadi server MCP di': 'When this switch is on, Zephyr becomes an MCP server at',
  'AI CLI di luar (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) bisa membaca pane, tab editor, dan settings — juga mengemudikan jendela ini: mengetik di terminal, membuka file, menjalankan command. Hanya loopback: tidak pernah terbuka ke jaringan.': 'External AI CLIs (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) can read panes, editor tabs and settings — and drive this window: type in the terminal, open files, run commands. Loopback only: never exposed to the network.',
