  'Folder yang belum dipercaya berjalan dalam': '신뢰되지 않은 폴더는 다음에서 실행됩니다:',
  ': file tetap bisa dibuka dan diedit, tapi tasks, debug, language server, dan ekstensi tidak dijalankan. Keputusan disimpan di': ': 파일은 열고 편집할 수 있지만 작업, 디버그, 언어 서버, 확장은 실행되지 않습니다. 결정은 다음에 저장됩니다:',
  'dan berlaku juga untuk subfolder.': '하위 폴더에도 적용됩니다.',
  'Saat switch ini hidup, Zephyr jadi server MCP di': '이 스위치를 켜면 Zephyr가 MCP 서버가 됩니다:',
  'AI CLI di luar (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) bisa membaca pane, tab editor, dan settings — juga mengemudikan jendela ini: mengetik di terminal, membuka file, menjalankan command. Hanya loopback: tidak pernah terbuka ke jaringan.': '외부 AI CLI(Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor)가 페인, 에디터 탭, 설정을 읽고 이 창을 조작할 수 있습니다. 루프백 전용이며 네트워크에 노출되지 않습니다.',
  'Belum ada koneksi. Begitu sebuah AI CLI menyapa': '아직 연결이 없습니다. AI CLI가 다음에 접속하면:',
  'atau memanggil tool, barisnya muncul di sini — bukti nyata, bukan klaim.': '또는 도구를 호출하면 여기에 행이 나타납니다 — 주장이 아닌 실제 증거입니다.',
  'Terbuka di port': '포트에서 열림:',
  ': apa pun yang berjalan sebagai user-mu bisa mengemudikan jendela ini selama tahu tokennya.': ': 사용자 권한으로 실행되는 모든 것이 토큰만 알면 이 창을 조작할 수 있습니다.',
  'hanya mengubah buffer tab, TIDAK menulis ke disk — penyimpanan tetap keputusanmu.': '는 탭 버퍼만 바꾸고 디스크에 쓰지 않습니다 — 저장은 당신의 결정입니다.',
  'dibatasi whitelist tampilan (tema, font, tab size); kredensial dan setting MCP sendiri tidak bisa diubah dari luar.': '는 표시 화이트리스트(테마, 글꼴, 탭 크기)로 제한됩니다. 자격 증명과 MCP 설정 자체는 외부에서 바꿀 수 없습니다.',
  'switch besar; port': '큰 스위치, 포트',
  'Belum ada. Ekstensi yang butuh runtime eksternal (Python, Java, Node, dll.) akan minta izin lewat dialog saat pertama kali memanggil': '아직 없습니다. 외부 런타임(Python, Java, Node 등)이 필요한 확장은 처음 호출할 때 대화상자로 권한을 요청합니다:',
  '— eksekusi selalu di sisi Rust dari binary yang kamu setujui, dan bisa dicabut di sini.': '— 실행은 항상 승인한 바이너리로 Rust 쪽에서 이루어지며 여기서 취소할 수 있습니다.',
