  'Saat switch ini hidup, Zephyr jadi server MCP di': '开启此开关后，Zephyr 将成为 MCP 服务器，地址：',
  'AI CLI di luar (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) bisa membaca pane, tab editor, dan settings — juga mengemudikan jendela ini: mengetik di terminal, membuka file, menjalankan command. Hanya loopback: tidak pernah terbuka ke jaringan.': '外部 AI CLI（Claude Code、Codex、Gemini CLI、opencode、Copilot CLI、Cursor）可读取窗格、编辑器标签和设置，并驱动此窗口。仅限回环，绝不暴露到网络。',
