  'Folder yang belum dipercaya berjalan dalam': 'Las carpetas no confiables se ejecutan en',
  ': file tetap bisa dibuka dan diedit, tapi tasks, debug, language server, dan ekstensi tidak dijalankan. Keputusan disimpan di': ': los archivos se pueden abrir y editar, pero las tareas, la depuración, los servidores de lenguaje y las extensiones no se ejecutan. La decisión se guarda en',
  'dan berlaku juga untuk subfolder.': 'y también se aplica a las subcarpetas.',
  'Saat switch ini hidup, Zephyr jadi server MCP di': 'Con este interruptor activado, Zephyr se convierte en servidor MCP en',
  'AI CLI di luar (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) bisa membaca pane, tab editor, dan settings — juga mengemudikan jendela ini: mengetik di terminal, membuka file, menjalankan command. Hanya loopback: tidak pernah terbuka ke jaringan.': 'Las CLI de IA externas (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) pueden leer paneles, pestañas del editor y ajustes — y manejar esta ventana. Solo loopback: nunca se expone a la red.',
  'Belum ada koneksi. Begitu sebuah AI CLI menyapa': 'Aún no hay conexiones. En cuanto una CLI de IA salude a',
  'atau memanggil tool, barisnya muncul di sini — bukti nyata, bukan klaim.': 'o llame a una herramienta, su línea aparece aquí — evidencia real, no una afirmación.',
  'Terbuka di port': 'Abierto en el puerto',
  ': apa pun yang berjalan sebagai user-mu bisa mengemudikan jendela ini selama tahu tokennya.': ': cualquier cosa que se ejecute como tu usuario puede manejar esta ventana si conoce el token.',
  'hanya mengubah buffer tab, TIDAK menulis ke disk — penyimpanan tetap keputusanmu.': 'solo cambia el búfer de la pestaña, NO escribe en disco — guardar sigue siendo tu decisión.',
  'dibatasi whitelist tampilan (tema, font, tab size); kredensial dan setting MCP sendiri tidak bisa diubah dari luar.': 'se limita a una lista blanca de visualización (tema, fuente, tamaño de tabulación); las credenciales y los ajustes de MCP no se pueden cambiar desde fuera.',
  'switch besar; port': 'interruptor grande; puerto',
  'Belum ada. Ekstensi yang butuh runtime eksternal (Python, Java, Node, dll.) akan minta izin lewat dialog saat pertama kali memanggil': 'Aún no hay ninguna. Las extensiones que necesiten un runtime externo (Python, Java, Node, etc.) pedirán permiso con un diálogo la primera vez que llamen a',
  '— eksekusi selalu di sisi Rust dari binary yang kamu setujui, dan bisa dicabut di sini.': '— la ejecución siempre ocurre en el lado Rust, desde un binario que aprobaste, y se puede revocar aquí.',
