  'Saat switch ini hidup, Zephyr jadi server MCP di': 'Quand ce commutateur est actif, Zephyr devient un serveur MCP sur',
  'AI CLI di luar (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) bisa membaca pane, tab editor, dan settings — juga mengemudikan jendela ini: mengetik di terminal, membuka file, menjalankan command. Hanya loopback: tidak pernah terbuka ke jaringan.': 'Les CLI IA externes (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) peuvent lire les volets, onglets et réglages — et piloter cette fenêtre. Loopback uniquement : jamais exposé au réseau.',
