  ': file tetap bisa dibuka dan diedit, tapi tasks, debug, language server, dan ekstensi tidak dijalankan. Keputusan disimpan di': ': Dateien lassen sich öffnen und bearbeiten, aber Tasks, Debug, Language Server und Erweiterungen laufen nicht. Die Entscheidung wird gespeichert in',
  'dan berlaku juga untuk subfolder.': 'und gilt auch für Unterordner.',
  'Saat switch ini hidup, Zephyr jadi server MCP di': 'Ist dieser Schalter an, wird Zephyr zum MCP-Server auf',
  'AI CLI di luar (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) bisa membaca pane, tab editor, dan settings — juga mengemudikan jendela ini: mengetik di terminal, membuka file, menjalankan command. Hanya loopback: tidak pernah terbuka ke jaringan.': 'Externe KI-CLIs (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) können Panes, Editor-Tabs und Einstellungen lesen — und dieses Fenster steuern. Nur Loopback: nie im Netzwerk erreichbar.',
  'Belum ada koneksi. Begitu sebuah AI CLI menyapa': 'Noch keine Verbindungen. Sobald eine KI-CLI',
  'atau memanggil tool, barisnya muncul di sini — bukti nyata, bukan klaim.': 'oder ein Tool aufruft, erscheint hier die Zeile — echter Beleg, keine Behauptung.',
  'Terbuka di port': 'Offen auf Port',
  ': apa pun yang berjalan sebagai user-mu bisa mengemudikan jendela ini selama tahu tokennya.': ': Alles, was als dein Benutzer läuft, kann dieses Fenster steuern, wenn es das Token kennt.',
  'hanya mengubah buffer tab, TIDAK menulis ke disk — penyimpanan tetap keputusanmu.': 'ändert nur den Tab-Puffer, schreibt NICHT auf die Platte — Speichern bleibt deine Entscheidung.',
  'dibatasi whitelist tampilan (tema, font, tab size); kredensial dan setting MCP sendiri tidak bisa diubah dari luar.': 'ist auf eine Anzeige-Whitelist beschränkt (Theme, Schrift, Tab-Größe); Zugangsdaten und MCP-Einstellungen selbst sind von außen nicht änderbar.',
  'switch besar; port': 'großer Schalter; Port',
  'Belum ada. Ekstensi yang butuh runtime eksternal (Python, Java, Node, dll.) akan minta izin lewat dialog saat pertama kali memanggil': 'Noch keine. Erweiterungen mit externer Runtime (Python, Java, Node usw.) fragen beim ersten Aufruf von',
  '— eksekusi selalu di sisi Rust dari binary yang kamu setujui, dan bisa dicabut di sini.': '— die Ausführung erfolgt immer auf der Rust-Seite, aus einer von dir bestätigten Binary, und kann hier widerrufen werden.',
