  'Saat switch ini hidup, Zephyr jadi server MCP di': 'Com este interruptor ligado, o Zephyr vira servidor MCP em',
  'AI CLI di luar (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) bisa membaca pane, tab editor, dan settings — juga mengemudikan jendela ini: mengetik di terminal, membuka file, menjalankan command. Hanya loopback: tidak pernah terbuka ke jaringan.': 'CLIs de IA externas (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) podem ler painéis, abas do editor e configurações — e controlar esta janela. Somente loopback: nunca exposto à rede.',
  'Belum ada koneksi. Begitu sebuah AI CLI menyapa': 'Nenhuma conexão ainda. Assim que uma CLI de IA acessar',
