  'hanya mengubah buffer tab, TIDAK menulis ke disk — penyimpanan tetap keputusanmu.': 'apenas altera o buffer da aba, NÃO grava no disco — salvar continua sendo sua decisão.',
  'dibatasi whitelist tampilan (tema, font, tab size); kredensial dan setting MCP sendiri tidak bisa diubah dari luar.': 'é limitado a uma lista branca de exibição (tema, fonte, tamanho da tabulação); credenciais e configurações do MCP não podem ser alteradas de fora.',
