  'Folder yang belum dipercaya berjalan dalam': 'تُشغَّل المجلدات غير الموثوقة في',
  ': file tetap bisa dibuka dan diedit, tapi tasks, debug, language server, dan ekstensi tidak dijalankan. Keputusan disimpan di': ': يمكن فتح الملفات وتحريرها، لكن المهام والتصحيح وخوادم اللغة والإضافات لا تعمل. يُحفظ القرار في',
  'dan berlaku juga untuk subfolder.': 'وينطبق أيضاً على المجلدات الفرعية.',
  'Saat switch ini hidup, Zephyr jadi server MCP di': 'عند تفعيل هذا المفتاح يصبح Zephyr خادم MCP على',
  'AI CLI di luar (Claude Code, Codex, Gemini CLI, opencode, Copilot CLI, Cursor) bisa membaca pane, tab editor, dan settings — juga mengemudikan jendela ini: mengetik di terminal, membuka file, menjalankan command. Hanya loopback: tidak pernah terbuka ke jaringan.': 'يمكن لأدوات AI CLI الخارجية (Claude Code وCodex وGemini CLI وopencode وCopilot CLI وCursor) قراءة اللوحات وتبويبات المحرر والإعدادات — والتحكم في هذه النافذة. على loopback فقط: لا يُفتح على الشبكة أبداً.',
  'Belum ada koneksi. Begitu sebuah AI CLI menyapa': 'لا اتصالات بعد. بمجرد أن تنادي أداة AI CLI',
  'atau memanggil tool, barisnya muncul di sini — bukti nyata, bukan klaim.': 'أو استدعت أداة، يظهر سطرها هنا — دليل حقيقي لا مجرد ادعاء.',
  'Terbuka di port': 'مفتوح على المنفذ',
  ': apa pun yang berjalan sebagai user-mu bisa mengemudikan jendela ini selama tahu tokennya.': ': أي شيء يعمل بحسابك يمكنه التحكم في هذه النافذة إن عرف الرمز.',
  'hanya mengubah buffer tab, TIDAK menulis ke disk — penyimpanan tetap keputusanmu.': 'يغيّر مخزن التبويب فقط ولا يكتب على القرص — الحفظ يبقى قرارك.',
  'dibatasi whitelist tampilan (tema, font, tab size); kredensial dan setting MCP sendiri tidak bisa diubah dari luar.': 'محدود بقائمة عرض بيضاء (السمة، الخط، حجم الجدولة)؛ لا يمكن تغيير بيانات الاعتماد وإعدادات MCP من الخارج.',
  'switch besar; port': 'مفتاح كبير؛ المنفذ',
  'Belum ada. Ekstensi yang butuh runtime eksternal (Python, Java, Node, dll.) akan minta izin lewat dialog saat pertama kali memanggil': 'لا شيء بعد. الإضافات التي تحتاج بيئة تشغيل خارجية (Python وJava وNode وغيرها) ستطلب الإذن عبر حوار عند أول استدعاء لـ',
  '— eksekusi selalu di sisi Rust dari binary yang kamu setujui, dan bisa dicabut di sini.': '— يجري التنفيذ دائماً في جانب Rust من ملف ثنائي وافقت عليه، ويمكن إلغاؤه هنا.',
